parameters.text:
=Analyze the following email. It may be a single job or a job-alert DIGEST containing many separate job listings. Identify EVERY distinct job listing and classify each one.

Subject: {{ $json.subject }}
From: {{ $json.from.text }}
Snippet: {{ $json.snippet }}
Body:
{{ $json.text }}

parameters.jsCode:
// One input item per email (Flutter AI Agent output). Emit one output item per RELEVANT job.
const agentItems = $input.all();
const emails = $('Get Email').all();
const out = [];

for (let i = 0; i < agentItems.length; i++) {
  const output = (agentItems[i].json && agentItems[i].json.output) || {};
  const jobs = Array.isArray(output.jobs) ? output.jobs : [];
  const email = (emails[i] && emails[i].json) || {};
  const senderEmail = (email.from && email.from.value && email.from.value[0] && email.from.value[0].address) || (email.from && email.from.text) || '';

  for (const job of jobs) {
    if (String(job.status || '').toUpperCase() !== 'RELEVANT') continue;

    const techs = Array.isArray(job.technologies) ? job.technologies : [];
    const reqs = Array.isArray(job.requirements) ? job.requirements : [];
    const techStr = techs.join(', ');
    const haystack = (techs.join(' ') + ' ' + (job.job_title || '') + ' ' + (job.summary || '')).toLowerCase();

    let score = 0;
    if (haystack.includes('flutter')) score += 40;
    if (haystack.includes('dart')) score += 20;
    if (haystack.includes('mobile') || haystack.includes('android') || haystack.includes('ios')) score += 15;
    if (haystack.includes('firebase')) score += 5;
    if (haystack.includes('rest')) score += 5;
    if (haystack.includes('getx') || haystack.includes('riverpod')) score += 5;
    if (String(job.work_type || '').toLowerCase().includes('remote')) score += 5;
    if (String(job.experience || '').trim() !== '') score += 5;
    if (score > 100) score = 100;

    const url = String(job.job_url || '').trim();
    const company = String(job.company || '').trim();
    const title = String(job.job_title || '').trim();
    const dedupKey = url ? url.toLowerCase() : (company.toLowerCase() + '|' + title.toLowerCase());

    out.push({ json: {
      'Application Date': '',
      'Application Time': '',
      'Job Found Date': $now.toFormat('yyyy-MM-dd'),
      'Job Found Time': $now.toFormat('HH:mm'),
      'Job Title': title,
      'Company': company,
      'Recruiter Name': job.recruiter_name || '',
      'Recruiter Email': job.recruiter_email || '',
      'Recruiter Phone': job.recruiter_phone || '',
      'Location': job.location || '',
      'Work Type': job.work_type || '',
      'Salary': job.salary || '',
      'Experience': job.experience || '',
      'Requirements': reqs.join('; '),
      'Technologies': techStr,
      'Apply Link': url,
      'Source': job.source || '',
      'Job Email': job.job_email || senderEmail,
      'Job Email Subject': job.job_subject || email.subject || '',
      'Status': 'New',
      'Notes': '',
      'Job Summary': job.summary || '',
      'Match Score': score,
      'Dedup Key': dedupKey,
    }});
  }
}

return out;

// Keep only jobs whose Dedup Key is not already in the sheet, and de-dup within this run.
const jobs = $('Job Data Extractor').all();
const existingRows = $input.all();

const existingKeys = new Set(
  existingRows
    .map(r => String((r.json && r.json['Dedup Key']) || '').trim().toLowerCase())
    .filter(k => k !== '')
);

const out = [];
const seenThisRun = new Set();

for (const item of jobs) {
  const key = String((item.json && item.json['Dedup Key']) || '').trim().toLowerCase();
  if (key === '') continue;
  if (existingKeys.has(key) || seenThisRun.has(key)) continue;
  seenThisRun.add(key);
  out.push({ json: item.json });
}

return out;
